import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.shared.fsclish.genericfsclish import GenericcFsclishCommand

__author__ = 'Sylwester Golonka'
__copyright__ = 'Copyright (C) 2018, Nokia'
__email__ = 'sylwester.golonka@nokia.com'


class SaveSnapshot(GenericcFsclishCommand):
    """Savesnapshot command class."""

    def __init__(self, connection, options, prompt=None, newline_chars=None, runner=None):
        """
        Savesnapshot command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(SaveSnapshot, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.ret_required = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "save snapshot"
        cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_config_name(line)
            except ParsingDone:
                pass
        return super(SaveSnapshot, self).on_new_line(line, is_full_line)

    _re_config_name = re.compile(r"Running\sstartup\sactions\sfor\sthe\sconfiguration\s(?P<CONFIG>.*)", re.IGNORECASE)

    def _parse_config_name(self, line):
        """
        Add config name to current_ret if parse in line.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(SaveSnapshot._re_config_name, line):
            self.current_ret["CONFIG"] = self._regex_helper.group("CONFIG")
            raise ParsingDone


